window.TADABBUR_NUR = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة النور (٢٤)، سورةٌ مدنيّةٌ فيها أحكامُ العفافِ والستر: حدُّ الزنا والقذف، وحادثةُ الإفك وبراءةُ عائشة، وآدابُ الاستئذانِ وغضِّ البصرِ والحجاب، وآيةُ النور، وأمثالُ أعمالِ الكفار. بُدئت بالحمد. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":24,"name":"النور","total_ayahs":64,"audio":[],"passages":[{"title":"حدُّ الزنا وصيانةُ الأعراض","range":[1,5],"theme":"فرضُ السورة، وحدُّ الزاني، وتحريمُ نكاحِ الزناة، وحدُّ القذف","verses":[{"n":1,"reflection":{"text":"«سورة أنزلناها وفرضناها وأنزلنا فيها آيات بينات لعلكم تذكرون» — هذه سورةٌ أنزلناها وأوجبنا العملَ بما فيها من الأحكام، وأنزلنا فيها آياتٍ واضحاتٍ لعلّكم تتّعظون؛ ففي هذا تعظيمُ شأنِ أحكامِ هذه السورةِ ووجوبُ العملِ بها، وأنّ غايتها التذكّرُ والاتّعاظ؛ فعظّم أحكامَ الله واعمل بها، وتذكّر بآياته البيّنات، فما فرضه الله يجب امتثاله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["أنزلناها وفرضناها"],"heart_state":{"text":"تعظيمُ أحكامِ الله والعملُ بها والاتّعاظُ بآياته."},"action":{"text":"عظّم أحكامَ الله التي فرضها واعمل بها، ولا تتهاون بشيءٍ منها؛ وتذكّر واتّعظ بآياته البيّناتِ في كتابه؛ فما أنزله الله وفرضه فلحكمةٍ وصلاحٍ لك، فالتزامه طاعةٌ، والاتّعاظُ به هدى."}},{"n":2,"reflection":{"text":"«الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة ولا تأخذكم بهما رأفة في دين الله إن كنتم تؤمنون بالله واليوم الآخر وليشهد عذابهما طائفة من المؤمنين» — الزانيةُ والزاني (غيرُ المحصنَين) اجلدوا كلَّ واحدٍ منهما مئةَ جلدة، ولا تمنعكم رأفةٌ بهما عن إقامةِ حدِّ الله إن كنتم مؤمنين، وليحضر عقوبتهما جماعةٌ من المؤمنين للعبرةِ والزجر؛ ففي هذا إقامةُ حدِّ الزنا صيانةً للأعراض، وأنّ الرأفةَ في تعطيلِ الحدودِ منافيةٌ للإيمان؛ فعظّم حدودَ الله ولا تتهاون بها بحجّةِ الرحمة، فإقامتها رحمةٌ للمجتمعِ وصيانةٌ للأعراض.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ولا تأخذكم بهما رأفة في دين الله"],"heart_state":{"text":"تعظيمُ حدودِ الله وصيانةُ الأعراض."},"action":{"text":"عظّم حدودَ الله وحرماتِه، ولا تتهاون بها بدعوى الرأفةِ والرحمة، فإقامتها صيانةٌ للأعراضِ ورحمةٌ للمجتمع؛ واحذر الزنا وأسبابه أشدَّ الحذر، فهو فاحشةٌ حرّمها الله وجعل لها حدًّا رادعًا."}},{"n":3,"reflection":{"text":"«الزاني لا ينكح إلا زانية أو مشركة والزانية لا ينكحها إلا زان أو مشرك وحرم ذلك على المؤمنين» — الزاني الخبيثُ لا يرغب في نكاحِ إلا زانيةٍ مثله أو مشركة، والزانيةُ كذلك، وحُرِّم نكاحُ الزناةِ على المؤمنين العفيفين؛ ففي هذا أنّ الخبيثَ يميل إلى الخبيث، وأنّ العفيفَ يُصان عن نكاحِ الزناة؛ فاحرص على العفّةِ في نفسك وفيمن تنكح، فالطيّبُ للطيّبين، فاطلب الزوجَ الصالحَ العفيف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على العفّةِ في النفسِ وفي اختيارِ الزوج."},"action":{"text":"احرص على العفّةِ في نفسك وفي اختيارِ من تنكح، فالطيّبون للطيّبات والخبيثون للخبيثات؛ فاطلب الزوجَ الصالحَ العفيفَ ذا الدين، وصُن نفسك عمّا يخلّ بعفّتك، فالعفّةُ صونٌ للنسلِ والعرض."}},{"n":4,"reflection":{"text":"«والذين يرمون المحصنات ثم لم يأتوا بأربعة شهداء فاجلدوهم ثمانين جلدة ولا تقبلوا لهم شهادة أبدا وأولئك هم الفاسقون» — والذين يقذفون النساءَ العفيفاتِ بالزنا ثم لم يأتوا بأربعةِ شهودٍ يشهدون على ما رموهنّ به، فاجلدوهم ثمانين جلدة، ولا تقبلوا لهم شهادةً أبدًا، وأولئك هم الخارجون عن طاعةِ الله؛ ففي هذا صيانةُ أعراضِ المؤمنين من القذف، وأنّ القاذفَ بلا بيّنةٍ يُحَدّ وتُردّ شهادته؛ فاحفظ لسانك عن قذفِ الأعراض، فالقذفُ بلا بيّنةٍ كبيرةٌ توجب الحدَّ والفسق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ولا تقبلوا لهم شهادة أبدا"],"heart_state":{"text":"حفظُ اللسانِ عن قذفِ الأعراضِ بلا بيّنة."},"action":{"text":"احفظ لسانك عن رميِ الأعراضِ العفيفةِ بالفاحشةِ بلا بيّنة، فالقذفُ كبيرةٌ توجب الحدَّ وردَّ الشهادةِ والفسق؛ فلا تتكلّم في عرضِ أحدٍ بظنٍّ أو إشاعة، وصُن لسانك، فأعراضُ المسلمين حِمى الله."}},{"n":5,"reflection":{"text":"«إلا الذين تابوا من بعد ذلك وأصلحوا فإن الله غفور رحيم» — إلا الذين تابوا من القذفِ بعد ذلك وأصلحوا أعمالهم، فإنّ الله غفورٌ لهم رحيمٌ بهم يقبل توبتهم؛ ففي هذا سعةُ رحمةِ الله بفتحِ بابِ التوبةِ حتى للقاذف، وأنّ التوبةَ الصادقةَ تجبّ ما قبلها؛ فمهما أذنبت فبابُ التوبةِ مفتوح، فتب وأصلح، فالله غفورٌ رحيمٌ يقبل التائبين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فإن الله غفور رحيم"],"heart_state":{"text":"المبادرةُ بالتوبةِ والإصلاحِ رجاءَ مغفرةِ الله."},"action":{"text":"مهما أذنبت ــ ولو بقذفٍ أو كبيرة ــ فبادر بالتوبةِ الصادقةِ وإصلاحِ عملك، فإنّ الله غفورٌ رحيمٌ يقبل التائبين؛ فلا تقنط من رحمته، والتوبةُ تجبّ ما قبلها، فأتبع السيّئةَ الحسنةَ تمحها."}}]},{"title":"اللِّعانُ بين الزوجين، وفضلُ الله","range":[6,10],"theme":"حكمُ من قذف زوجه، ومباهلةُ اللعان، والامتنانُ بفضلِ الله ورحمته","verses":[{"n":6,"reflection":{"text":"«والذين يرمون أزواجهم ولم يكن لهم شهداء إلا أنفسهم فشهادة أحدهم أربع شهادات بالله إنه لمن الصادقين» — والذين يقذفون زوجاتهم بالزنا ولا شهودَ لهم إلا أنفسهم، فليشهد الزوجُ أربعَ شهاداتٍ بالله إنه لمن الصادقين فيما رماها به؛ ففي هذا حكمُ اللعانِ الذي يحفظ حقَّ الزوجِ ويصون العرض، وأنّ الشرعَ جعل مخرجًا عادلًا عند فقدِ البيّنة؛ فتأمّل حكمةَ الشرعِ في صونِ الأعراضِ وحفظِ الحقوق، والزم الصدقَ في يمينك، فاليمينُ بالله أمرٌ عظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ حكمةِ الشرعِ في صونِ الأعراضِ ولزومُ الصدق."},"action":{"text":"تأمّل حكمةَ الشرعِ في اللعانِ الذي يصون الأعراضَ ويحفظ الحقوقَ عند فقدِ البيّنة، والزم الصدقَ في أيمانك وشهاداتك؛ فالحلفُ بالله أمرٌ عظيم، فلا تحلف إلا صادقًا، واحذر اليمينَ الكاذبةَ فعقوبتها شديدة."}},{"n":7,"reflection":{"text":"«والخامسة أن لعنت الله عليه إن كان من الكاذبين» — والشهادةُ الخامسةُ يدعو فيها على نفسه أنّ لعنةَ الله عليه إن كان كاذبًا في رميها؛ ففي هذا تغليظُ اليمينِ بالدعاءِ على النفسِ باللعنةِ إن كذب، وأنّ ذلك يردع الكاذب؛ فاحذر اليمينَ الكاذبةَ التي يُدعى فيها على النفسِ باللعنة، فمن كذب فيها استحقّ اللعنة، فصُن لسانك عن الكذبِ في الأيمان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اليمينِ الكاذبةِ الموجبةِ للّعنة."},"action":{"text":"احذر أن تحلف يمينًا كاذبةً تُدعى فيها على نفسك باللعنةِ أو الغضب، فمن كذب فيها استحقّ ما دعا به على نفسه؛ فالزم الصدقَ في أيمانك، ولا تجعل يمينك بالله جسرًا إلى الباطلِ والكذب."}},{"n":8,"reflection":{"text":"«ويدرأ عنها العذاب أن تشهد أربع شهادات بالله إنه لمن الكاذبين» — ويُدفَع عن الزوجةِ حدُّ الزنا بأن تشهد أربعَ شهاداتٍ بالله إنّ زوجها لمن الكاذبين فيما رماها به؛ ففي هذا عدلُ الشرعِ في إعطاءِ الزوجةِ حقَّ الدفاعِ عن نفسها، وأنّ الشرعَ يصون البريءَ من العقوبة؛ فتأمّل عدلَ الشرعِ الذي يصون البريءَ ويعطي كلَّ ذي حقٍّ حقّه، والزم العدلَ والإنصافَ في أحكامك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ عدلِ الشرعِ في صونِ البريءِ وإعطاءِ الحقوق."},"action":{"text":"تأمّل عدلَ الشرعِ الذي يصون البريءَ من العقوبةِ ويعطي كلَّ ذي حقٍّ حقّه، كما درأ عن الزوجةِ العذابَ بلعانها؛ والزم العدلَ والإنصافَ في أحكامك ومعاملاتك، ولا تعجل بالحكمِ قبل تمامِ البيّنة."}},{"n":9,"reflection":{"text":"«والخامسة أن غضب الله عليها إن كان من الصادقين» — والشهادةُ الخامسةُ تدعو فيها على نفسها أنّ غضبَ الله عليها إن كان زوجها صادقًا فيما رماها به؛ ففي هذا تغليظُ يمينها بالدعاءِ على نفسها بالغضبِ إن كذبت، وأنّ ذلك يردعها؛ فاحذر الكذبَ في اليمين، فمن كذب فيها بعد الدعاءِ على نفسه بالغضبِ استحقّه؛ فالصدقُ نجاة، والكذبُ في الأيمانِ هلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكذبِ في اليمينِ ولزومُ الصدق."},"action":{"text":"احذر الكذبَ في اليمينِ التي تُدعى فيها على نفسك بالغضبِ أو اللعنة، فمن كذب استحقّ ما دعا به؛ فالزم الصدقَ في كلِّ يمينٍ وشهادة، فالصدقُ منجاةٌ والكذبُ في الأيمانِ من كبائرِ الذنوب."}},{"n":10,"reflection":{"text":"«ولولا فضل الله عليكم ورحمته وأن الله تواب حكيم» — ولولا فضلُ الله عليكم ورحمتُه بشرعِ هذه الأحكامِ التي تصون أعراضكم، وأنّ الله توّابٌ يقبل التوبة، حكيمٌ في تشريعه، لعاجلكم بالعقوبة؛ ففي هذا امتنانٌ بفضلِ الله ورحمتِه في التشريعِ وقبولِ التوبة، وإثباتُ حكمتِه؛ فاشكر فضلَ الله ورحمته في أحكامه التي تصونك، وارجُ توبته، واعلم أنّ شرعه كلَّه حكمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["فضل الله عليكم ورحمته","تواب حكيم"],"heart_state":{"text":"شكرُ فضلِ الله ورحمتِه في التشريع، ورجاءُ توبته."},"action":{"text":"اشكر فضلَ الله ورحمته في أحكامه التي شرعها لصونِ أعراضك ومصالحك، وارجُ توبته فهو توّابٌ يقبل التائبين، واعلم أنّ شرعه كلَّه حكمةٌ ورحمة؛ فسلّم لأحكامه واعمل بها، فما شرع شيئًا إلا لخيرك."}}]},{"title":"حادثةُ الإفكِ وبراءةُ عائشة","range":[11,18],"theme":"براءةُ أمِّ المؤمنين، وأدبُ المؤمنِ عند سماعِ الإشاعة، وعِظَمُ الخوضِ في الأعراض","verses":[{"n":11,"reflection":{"text":"«إن الذين جاءوا بالإفك عصبة منكم لا تحسبوه شرا لكم بل هو خير لكم لكل امرئ منهم ما اكتسب من الإثم والذي تولى كبره منهم له عذاب عظيم» — إنّ الذين جاؤوا بالكذبِ البهتانِ (في رميِ عائشةَ رضي الله عنها) جماعةٌ منكم، لا تظنّوه شرًّا لكم بل هو خيرٌ لكم (ببراءتها ونزولِ آياتٍ تُتلى)، لكلِّ واحدٍ منهم جزاءُ ما اكتسب من الإثم، والذي تحمّل معظمَ الإفكِ (رأسُ النفاق) له عذابٌ عظيم؛ ففي هذا أنّ ما يظنّه المؤمنُ شرًّا قد يكون خيرًا، وأنّ خوضَ الأعراضِ كبيرة؛ فأحسن الظنَّ بالله في المصائب، فقد يكون فيها خير، واحذر الخوضَ في الأعراض.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إحسانُ الظنِّ بالله في المصائب، والحذرُ من خوضِ الأعراض."},"action":{"text":"أحسن الظنَّ بالله فيما يصيبك من بلاءٍ أو ابتلاءٍ في عرضك، فقد يكون فيه خيرٌ لا تعلمه؛ واحذر أشدَّ الحذرِ من الخوضِ في أعراضِ المسلمين، ولا سيّما أهلِ الفضل، فهو من كبائرِ الذنوب."},"sabab":{"text":"نزلت في حادثةِ الإفكِ حين رمى أهلُ النفاقِ أمَّ المؤمنين عائشةَ رضي الله عنها بالبهتان، فبرّأها الله من فوقِ سبعِ سماوات.","source":"صحيح البخاري ومسلم (حديث الإفك)","grade":"ma'thur"}},{"n":12,"reflection":{"text":"«لولا إذ سمعتموه ظن المؤمنون والمؤمنات بأنفسهم خيرا وقالوا هذا إفك مبين» — هلّا حين سمعتم الإفكَ ظنّ المؤمنون والمؤمناتُ بإخوانهم خيرًا، وقالوا: هذا كذبٌ واضح؟ ففي هذا تعليمُ حسنِ الظنِّ بالمؤمنين وردِّ الإشاعةِ الباطلة، وأنّ المؤمنَ كنفسِ أخيه؛ فأحسن الظنَّ بإخوانك المؤمنين عند سماعِ ما يُقال فيهم، وردَّ الإشاعةَ الباطلةَ ولا تصدّقها، فالأصلُ في المسلمِ الستر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ظن المؤمنون والمؤمنات بأنفسهم خيرا"],"heart_state":{"text":"حسنُ الظنِّ بالمؤمنين وردُّ الإشاعاتِ الباطلة."},"action":{"text":"أحسن الظنَّ بإخوانك المؤمنين عند سماعِ ما يُقال في أعراضهم، وردَّ الإشاعةَ الباطلةَ فقل «هذا إفك مبين» ولا تنقلها؛ فالأصلُ في المسلمِ العفافُ والستر، فلا تُسِئ الظنَّ ولا تصدّق كلَّ ما يُقال."}},{"n":13,"reflection":{"text":"«لولا جاءوا عليه بأربعة شهداء فإذ لم يأتوا بالشهداء فأولئك عند الله هم الكاذبون» — هلّا جاء القاذفون على ما رموا به أربعةَ شهداء؟ فإذ لم يأتوا بهم فأولئك عند الله هم الكاذبون؛ ففي هذا أنّ الاتّهامَ بلا بيّنةٍ كذبٌ عند الله، وأنّ الأعراضَ لا تُنتهَك بالظنون؛ فلا تتّهم أحدًا بلا بيّنةٍ شرعيّة، فمن قذف بلا أربعةِ شهداءَ فهو كاذبٌ عند الله، فاحفظ لسانك عن الأعراض.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاتّهامِ بلا بيّنة، وحفظُ الأعراض."},"action":{"text":"لا تتّهم أحدًا في عرضه بلا بيّنةٍ شرعيّةٍ تامّة، فمن رمى محصنًا بلا أربعةِ شهداءَ فهو كاذبٌ عند الله؛ فاحفظ لسانك عن الخوضِ في أعراضِ الناسِ بالظنونِ والإشاعات، فأعراضهم حِمًى لا يُنتهَك بلا برهان."}},{"n":14,"reflection":{"text":"«ولولا فضل الله عليكم ورحمته في الدنيا والآخرة لمسكم في ما أفضتم فيه عذاب عظيم» — ولولا فضلُ الله عليكم ورحمتُه في الدنيا والآخرةِ لأصابكم بسببِ ما خضتم فيه من الإفكِ عذابٌ عظيم؛ ففي هذا التحذيرُ من الخوضِ في الأعراض، وأنّ فضلَ الله ورحمتَه أنقذا الخائضين من عذابٍ عظيم؛ فاحذر الخوضَ في أعراضِ المسلمين، فإنه موجبٌ للعذابِ لولا رحمةُ الله، فاشكر فضله واحفظ لسانك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الخوضِ في الأعراضِ الموجبِ للعذاب."},"action":{"text":"احذر الخوضَ في أعراضِ المسلمين ونقلَ الإشاعاتِ عنهم، فإنه موجبٌ لعذابٍ عظيمٍ لولا فضلُ الله ورحمته؛ فاشكر فضله بحفظِ لسانك، ولا تجعل عرضَ أخيك مادّةً لحديثك ومجلسك، فالأعراضُ حرماتٌ عظام."}},{"n":15,"reflection":{"text":"«إذ تلقونه بألسنتكم وتقولون بأفواهكم ما ليس لكم به علم وتحسبونه هينا وهو عند الله عظيم» — حين يأخذ بعضكم الإفكَ عن بعضٍ بألسنتكم وتقولون بأفواهكم ما لا علمَ لكم به، وتحسبونه هيّنًا سهلًا وهو عند الله عظيمٌ في الإثم؛ ففي هذا أنّ كثيرًا من الذنوبِ يُستهان بها وهي عظيمةٌ عند الله، وأنّ نقلَ الكلامِ بلا علمٍ إثم؛ فلا تستهن بذنبٍ ولا سيّما في الأعراض، فربّ كلمةٍ تحسبها هيّنةً وهي عند الله عظيمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["تحسبونه هينا وهو عند الله عظيم"],"heart_state":{"text":"عدمُ الاستهانةِ بالذنوبِ ولا سيّما في الأعراض."},"action":{"text":"لا تستهن بذنبٍ ولو حسبته هيّنًا، ولا سيّما الكلامُ في الأعراضِ ونقلُ ما لا علمَ لك به؛ فربّ كلمةٍ تحسبها يسيرةً وهي عند الله عظيمة؛ فزِن كلماتك بميزانِ الله لا بميزانِ الناس، واحذر ما تستصغره النفوس."}},{"n":16,"reflection":{"text":"«ولولا إذ سمعتموه قلتم ما يكون لنا أن نتكلم بهذا سبحانك هذا بهتان عظيم» — وهلّا حين سمعتم الإفكَ قلتم: ما ينبغي لنا أن نتكلّم بهذا، تنزّهت يا ربّنا، هذا كذبٌ عظيم؟ ففي هذا تعليمُ الأدبِ عند سماعِ الباطل: التنزّهُ عنه وإنكارُه، وأنّ المؤمنَ يستعظم الخوضَ في الأعراض؛ فإذا سمعت باطلًا في عرضِ أخيك فأنكره وتنزّه عنه، وقل «هذا بهتان عظيم»، ولا تشارك في نقله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["سبحانك هذا بهتان عظيم"],"heart_state":{"text":"إنكارُ الباطلِ عند سماعه والتنزّهُ عن نقله."},"action":{"text":"إذا سمعت باطلًا أو إفكًا في عرضِ أخيك فأنكره ولا تشارك في نقله، وتنزّه عنه قائلًا «سبحانك هذا بهتان عظيم»؛ فالمؤمنُ يستعظم الخوضَ في الأعراض، ويردّ الباطلَ عند سماعه، ولا يكون جسرًا لنقله."}},{"n":17,"reflection":{"text":"«يعظكم الله أن تعودوا لمثله أبدا إن كنتم مؤمنين» — يعظكم الله وينهاكم أن تعودوا لمثلِ هذا الخوضِ في الأعراضِ أبدًا إن كنتم مؤمنين حقًّا؛ ففي هذا أنّ الإيمانَ يمنع من العودةِ لمثلِ ذلك الذنب، وأنّ الموعظةَ تقتضي الانتهاء؛ فاتّعظ بموعظةِ الله وانتهِ عن الخوضِ في الأعراض، ولا تعد لمثله أبدًا، فذلك مقتضى إيمانك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بموعظةِ الله والانتهاءُ عن الذنب."},"action":{"text":"اتّعظ بموعظةِ الله وانتهِ عن الخوضِ في الأعراضِ ونقلِ الإشاعات، ولا تعد لمثله أبدًا؛ فالإيمانُ الصادقُ يمنعك من العودةِ للذنبِ بعد الموعظة؛ فاجعل موعظةَ الله رادعًا لك، فالمؤمنُ لا يُلدَغ من جحرٍ مرّتين."}},{"n":18,"reflection":{"text":"«ويبين الله لكم الآيات والله عليم حكيم» — ويوضّح الله لكم الآياتِ والأحكامَ لتعملوا بها، والله عليمٌ بأحوالكم حكيمٌ في تشريعه؛ ففي هذا أنّ الله يبيّن الأحكامَ رحمةً بالعباد، وأنّ علمه وحكمته محيطان؛ فتلقَّ بيانَ الله لآياته بالقبولِ والعمل، واعلم أنّ ما شرعه عن علمٍ وحكمة، فسلّم لأحكامه واعمل بها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["والله عليم حكيم"],"heart_state":{"text":"تلقّي بيانِ الله بالقبولِ والعملِ لعلمه وحكمته."},"action":{"text":"تلقَّ بيانَ الله لآياته وأحكامه بالقبولِ والتسليمِ والعمل، واعلم أنّ ما شرعه صادرٌ عن علمٍ تامٍّ وحكمةٍ بالغة؛ فهو عليمٌ حكيمٌ لا يشرع إلا لخيرك؛ فاعمل بما بيّنه، ولا تعترض على حكمةٍ خفيت عليك."}}]},{"title":"النهيُ عن إشاعةِ الفاحشةِ واتّباعِ الشيطان","range":[19,21],"theme":"عذابُ محبّي إشاعةِ الفاحشة، والنهيُ عن اتّباعِ خطواتِ الشيطان","verses":[{"n":19,"reflection":{"text":"«إن الذين يحبون أن تشيع الفاحشة في الذين آمنوا لهم عذاب أليم في الدنيا والآخرة والله يعلم وأنتم لا تعلمون» — إنّ الذين يحبّون أن تنتشر الفاحشةُ وأخبارها في المؤمنين لهم عذابٌ أليمٌ في الدنيا والآخرة، والله يعلم عواقبَ الأمورِ ومصالحَ عباده وأنتم لا تعلمون؛ ففي هذا أنّ مجردَ محبّةِ إشاعةِ الفاحشةِ في المؤمنين كبيرةٌ توجب العذاب، وأنّ ذلك يهدم المجتمع؛ فاحذر أن تحبَّ إشاعةَ الفاحشةِ أو تسعى فيها، بل استر على المسلمين وأحبَّ لهم الخير.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يحبون أن تشيع الفاحشة في الذين آمنوا"],"heart_state":{"text":"الحذرُ من محبّةِ إشاعةِ الفاحشةِ والسترُ على المسلمين."},"action":{"text":"احذر أن تحبَّ أو تسعى في إشاعةِ الفاحشةِ وأخبارِ السوءِ في المؤمنين، فمجردُ محبّةِ ذلك كبيرةٌ توجب العذاب؛ بل استر على المسلمين عوراتهم، وأحبَّ لهم العفافَ والستر؛ فمن ستر مسلمًا ستره الله."}},{"n":20,"reflection":{"text":"«ولولا فضل الله عليكم ورحمته وأن الله رءوف رحيم» — ولولا فضلُ الله عليكم ورحمتُه، وأنّ الله رؤوفٌ رحيمٌ بكم، لعاجلكم بالعقوبةِ على ذنوبكم؛ ففي هذا امتنانٌ بفضلِ الله ورأفتِه ورحمته، وأنها سببُ إمهالِ العاصي؛ فاشكر فضلَ الله ورحمته التي أمهلتك، وبادر بالتوبةِ قبل أن يأخذك، فرأفتُه ورحمتُه فرصةٌ للرجوعِ لا للاغترار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["أن الله رءوف رحيم"],"heart_state":{"text":"شكرُ رأفةِ الله ورحمته، والمبادرةُ بالتوبة."},"action":{"text":"اشكر فضلَ الله ورأفته ورحمته التي أمهلتك ولم تعاجلك بالعقوبة، وبادر بالتوبةِ والإصلاحِ قبل أن يأخذك؛ فرحمتُه فرصةٌ للرجوعِ إليه لا للتمادي في الذنب؛ فمن عرف رأفةَ ربّه استحيا أن يعصيه."}},{"n":21,"reflection":{"text":"«يا أيها الذين آمنوا لا تتبعوا خطوات الشيطان ومن يتبع خطوات الشيطان فإنه يأمر بالفحشاء والمنكر ولولا فضل الله عليكم ورحمته ما زكى منكم من أحد أبدا ولكن الله يزكي من يشاء والله سميع عليم» — يا أيها المؤمنون لا تتّبعوا طرقَ الشيطانِ وتزيينَه، ومن يتّبع خطواته فإنه يأمر بالفحشاءِ والمنكر، ولولا فضلُ الله ورحمتُه ما طهُر منكم أحدٌ من الذنوب، ولكنّ الله يطهّر من يشاء بتوفيقه، والله سميعٌ عليم؛ ففي هذا التحذيرُ من اتّباعِ الشيطانِ خطوةً خطوة، وأنّ التزكيةَ بفضلِ الله لا بحولِ العبد؛ فاحذر خطواتِ الشيطانِ ولو صغيرة، واطلب التزكيةَ من الله، فبفضله يطهر القلب.","source":"تفسير السعدي","grade":"ma'thur"},"names":["لا تتبعوا خطوات الشيطان","الله يزكي من يشاء"],"heart_state":{"text":"الحذرُ من خطواتِ الشيطان، وطلبُ التزكيةِ من الله."},"action":{"text":"احذر اتّباعَ خطواتِ الشيطانِ ولو بدت صغيرةً، فإنها تقود إلى الفحشاءِ والمنكر؛ واطلب التزكيةَ والطهارةَ من الله فهو الذي يزكّي من يشاء، ولولا فضله ما طهُر أحد؛ فالجأ إليه في تطهيرِ قلبك وعملك."}}]},{"title":"العفوُ والصفح، ووعيدُ قذفةِ المحصنات","range":[22,26],"theme":"الحضُّ على العفو، وعقوبةُ رميِ العفيفات، والطيّبُ للطيّبين","verses":[{"n":22,"reflection":{"text":"«ولا يأتل أولو الفضل منكم والسعة أن يؤتوا أولي القربى والمساكين والمهاجرين في سبيل الله وليعفوا وليصفحوا ألا تحبون أن يغفر الله لكم والله غفور رحيم» — ولا يحلف أهلُ الفضلِ والسعةِ منكم ألّا يعطوا أقاربهم والمساكينَ والمهاجرين (ممّن أخطأ في حقّهم)، وليعفوا وليصفحوا عمّن أساء، ألا تحبّون أن يغفر الله لكم كما تعفون؟ والله غفورٌ رحيم؛ ففي هذا الحضُّ على العفوِ والصفحِ ومقابلةِ الإساءةِ بالإحسان، وأنّ من عفا عفا الله عنه؛ فاعفُ عمّن أساء إليك وأحسن إليه، فكما تحبّ أن يغفر الله لك فاغفر لعباده، فالجزاءُ من جنسِ العمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وليعفوا وليصفحوا","ألا تحبون أن يغفر الله لكم"],"heart_state":{"text":"العفوُ والصفحُ عمّن أساء رجاءَ مغفرةِ الله."},"action":{"text":"اعفُ عمّن أساء إليك وأحسن إليه ولا تقطع معروفك عنه، فكما تحبّ أن يغفر الله لك فاغفر لعباده؛ فالجزاءُ من جنسِ العمل، ومن عفا عفا الله عنه؛ فقابل الإساءةَ بالإحسان، وأدِم صلتك بمن أخطأ في حقّك."}},{"n":23,"reflection":{"text":"«إن الذين يرمون المحصنات الغافلات المؤمنات لعنوا في الدنيا والآخرة ولهم عذاب عظيم» — إنّ الذين يقذفون النساءَ العفيفاتِ البريئاتِ من الفاحشةِ المؤمنات لُعِنوا (طُرِدوا من رحمةِ الله) في الدنيا والآخرة، ولهم عذابٌ عظيم؛ ففي هذا شدّةُ وعيدِ قاذفِ المحصنات، وأنّ قذفَ العفيفةِ من كبائرِ الذنوب؛ فاحذر أشدَّ الحذرِ من رميِ الأعراضِ العفيفة، فإنه موجبٌ للعنِ والعذابِ العظيم، فاحفظ لسانك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لعنوا في الدنيا والآخرة"],"heart_state":{"text":"الحذرُ الشديدُ من قذفِ المحصناتِ العفيفات."},"action":{"text":"احذر أشدَّ الحذرِ من رميِ النساءِ العفيفاتِ المؤمناتِ بالفاحشة، فهو من كبائرِ الذنوبِ الموجبةِ للعنِ في الدنيا والآخرةِ والعذابِ العظيم؛ فاحفظ لسانك عن أعراضِ المسلمين، ولا تخض فيها بظنٍّ أو إشاعة."}},{"n":24,"reflection":{"text":"«يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون» — يوم تشهد على القاذفين وغيرهم ألسنتُهم وأيديهم وأرجلهم بما كانوا يعملون من المعاصي؛ ففي هذا أنّ الجوارحَ تشهد على صاحبها يوم القيامة، وأنّ العملَ محفوظٌ ينطق به الأعضاء؛ فراقب جوارحك فيما تعمل، فإنها ستشهد عليك، فاستعملها في الطاعةِ لا في المعصية، فكلُّ عضوٍ شاهدٌ عليك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الجوارحِ إذ تشهد على صاحبها."},"action":{"text":"راقب جوارحك ــ لسانك ويدك ورجلك ــ فيما تعمل، فإنها ستشهد عليك يوم القيامةِ بما عملت؛ فاستعملها في طاعةِ الله لا في معصيته، واستحضر أنّ أعضاءك رقباءُ عليك، فمن راقب جوارحه أحسن استعمالها."}},{"n":25,"reflection":{"text":"«يومئذ يوفيهم الله دينهم الحق ويعلمون أن الله هو الحق المبين» — يومئذٍ يوفّيهم الله جزاءهم العدلَ الحقّ، ويعلمون علمَ يقينٍ أنّ الله هو الحقُّ الذي يُظهِر الحقّ ويبيّنه؛ ففي هذا أنّ الجزاءَ يوم القيامةِ عدلٌ حقّ، وأنّ حقّيّةَ الله تنكشف للجميع؛ فاعمل موقنًا بأنّ الله سيوفّيك جزاءك بالحقِّ والعدل، وأنه الحقُّ المبين، فاطلب رضاه واحذر عدله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الله هو الحق المبين"],"heart_state":{"text":"اليقينُ بعدلِ الله في الجزاءِ وأنه الحقُّ المبين."},"action":{"text":"اعمل موقنًا بأنّ الله سيوفّيك جزاءك يوم القيامةِ بالعدلِ التامّ، وأنّ حقّيّته تنكشف للجميع؛ فأحسن عملك رجاءَ ثوابه، واحذر معصيته خشيةَ عدله؛ فمن أيقن أنّ الله هو الحقُّ المبينُ استقام على أمره."}},{"n":26,"reflection":{"text":"«الخبيثات للخبيثين والخبيثون للخبيثات والطيبات للطيبين والطيبون للطيبات أولئك مبرءون مما يقولون لهم مغفرة ورزق كريم» — الكلماتُ والأفعالُ الخبيثةُ تليق بالخبيثين، والطيّباتُ تليق بالطيّبين، وكذلك الأزواج؛ والطيّبون كعائشةَ والنبيِّ ﷺ مبرَّءون ممّا يقول أهلُ الإفك، لهم مغفرةٌ ورزقٌ كريمٌ في الجنّة؛ ففي هذا أنّ الطيّبَ يليق به الطيّب، وأنّ الله برّأ أهلَ الطهارةِ من الإفك؛ فكن طيّبًا في قولك وعملك وصحبتك، فالطيّبُ للطيّبين، والله يبرّئ أهلَ الطهارةِ ويكرمهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الطيبات للطيبين والطيبون للطيبات","مغفرة ورزق كريم"],"heart_state":{"text":"طلبُ الطِّيبِ في القولِ والعملِ والصحبة."},"action":{"text":"كن طيّبًا في قولك وعملك ومطعمك واختيارِ صحبتك وزوجك، فالطيّبون للطيّبات والطيّباتُ للطيّبين؛ فمن طاب باطنه وظاهره برّأه الله وأكرمه بالمغفرةِ والرزقِ الكريم؛ فاطلب الطِّيبَ في كلِّ شأنك."}}]},{"title":"آدابُ الاستئذانِ ودخولِ البيوت","range":[27,29],"theme":"النهيُ عن دخولِ البيوتِ بلا استئذان، ورعايةُ الخصوصية","verses":[{"n":27,"reflection":{"text":"«يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها ذلكم خير لكم لعلكم تذكرون» — يا أيها المؤمنون لا تدخلوا بيوتًا ليست بيوتكم حتى تستأذنوا وتسلّموا على أهلها، ذلك خيرٌ لكم من الدخولِ بغتة، لعلّكم تتذكّرون فتعملوا بأدبِ الله؛ ففي هذا تشريعُ أدبِ الاستئذانِ صيانةً للحرماتِ والخصوصية، وأنّ ذلك خيرٌ للمؤمن؛ فالزم الاستئذانَ والسلامَ قبل دخولِ بيوتِ غيرك، فذلك أدبُ الإسلامِ وصونٌ للحرمات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["حتى تستأنسوا وتسلموا على أهلها"],"heart_state":{"text":"لزومُ أدبِ الاستئذانِ والسلامِ صيانةً للحرمات."},"action":{"text":"لا تدخل بيتَ غيرك حتى تستأذن وتسلّم على أهله، والزم هذا الأدبَ صيانةً لحرماتِ الناسِ وخصوصيّاتهم؛ فالاستئذانُ خيرٌ لك ولهم، وأدبٌ من آدابِ الإسلام؛ فلا تفاجئ أحدًا في بيته، واحترم خصوصيّته."}},{"n":28,"reflection":{"text":"«فإن لم تجدوا فيها أحدا فلا تدخلوها حتى يؤذن لكم وإن قيل لكم ارجعوا فارجعوا هو أزكى لكم والله بما تعملون عليم» — فإن لم تجدوا في البيوتِ أحدًا يأذن لكم فلا تدخلوها حتى يُؤذَن لكم، وإن قيل لكم ارجعوا فارجعوا ولا تلحّوا، هو أطهرُ لكم، والله بما تعملون عليم؛ ففي هذا تمامُ أدبِ الاستئذان، وأنّ الرجوعَ عند المنعِ أزكى، وأنّ الله عليمٌ بالأعمال؛ فإذا مُنِعت من الدخولِ فارجع بلا حرجٍ ولا إلحاح، فذلك أزكى لك، واعلم أنّ الله يراقب أدبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وإن قيل لكم ارجعوا فارجعوا هو أزكى لكم"],"heart_state":{"text":"التأدّبُ بالرجوعِ عند المنعِ بلا إلحاح."},"action":{"text":"إذا لم يُؤذَن لك بالدخولِ أو قيل لك ارجع فارجع بنفسٍ طيّبةٍ بلا إلحاحٍ ولا حرج، فذلك أطهرُ لك وأزكى؛ واعلم أنّ الله عليمٌ بعملك يراقب أدبك؛ فالتأدّبُ عند المنعِ من كمالِ الإيمانِ وحسنِ الخُلق."}},{"n":29,"reflection":{"text":"«ليس عليكم جناح أن تدخلوا بيوتا غير مسكونة فيها متاع لكم والله يعلم ما تبدون وما تكتمون» — ليس عليكم إثمٌ أن تدخلوا بيوتًا غيرَ مسكونةٍ (كالخاناتِ والأسواق) فيها منفعةٌ لكم بلا استئذان، والله يعلم ما تظهرون وما تخفون؛ ففي هذا تيسيرُ الشرعِ في البيوتِ العامّة، وأنّ الله يعلم الظاهرَ والباطن؛ فتأمّل يُسرَ الشرعِ وسعته، وراقب الله عالمَ السرِّ والعلن في كلِّ أحوالك، فهو يعلم ما تبدي وما تكتم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ يُسرِ الشرع، ومراقبةُ الله عالمِ السرِّ والعلن."},"action":{"text":"تأمّل يُسرَ الشرعِ الذي رخّص في دخولِ البيوتِ العامّةِ بلا استئذان؛ وراقب الله عالمَ ما تبدي وما تكتم في كلِّ أحوالك، فلا يخفى عليه شيء؛ فطهّر باطنك كظاهرك، واستحضر علمه بك، فمن راقب الله استقام."}}]},{"title":"غضُّ البصرِ وحفظُ الفروجِ والحجاب","range":[30,31],"theme":"أمرُ المؤمنين والمؤمناتِ بغضِّ البصرِ وحفظِ الفروجِ والحجاب","verses":[{"n":30,"reflection":{"text":"«قل للمؤمنين يغضوا من أبصارهم ويحفظوا فروجهم ذلك أزكى لهم إن الله خبير بما يصنعون» — قل للمؤمنين يكفّوا أبصارهم عن النظرِ إلى ما حرّم الله، ويحفظوا فروجهم عن الحرام، ذلك أطهرُ لهم وأزكى، إنّ الله خبيرٌ بما يصنعون؛ ففي هذا أمرُ الرجالِ بغضِّ البصرِ وحفظِ الفرج، وأنّ ذلك طهارةٌ للقلب؛ فغضَّ بصرك عمّا حرّم الله واحفظ فرجك، فذلك أزكى لقلبك وأصونُ لدينك، واعلم أنّ الله خبيرٌ بنظرك، فراقبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يغضوا من أبصارهم ويحفظوا فروجهم","ذلك أزكى لهم"],"heart_state":{"text":"غضُّ البصرِ وحفظُ الفرجِ طهارةً للقلب."},"action":{"text":"غضَّ بصرك عمّا حرّم الله من النظرِ إلى العوراتِ والمحرَّمات، واحفظ فرجك عن الحرام؛ فذلك أزكى لقلبك وأطهرُ لنفسك وأصونُ لدينك؛ واعلم أنّ الله خبيرٌ بنظرك وصنيعك، فراقبه في خلواتك، فالنظرةُ سهمٌ من سهامِ إبليس."}},{"n":31,"reflection":{"text":"«وقل للمؤمنات يغضضن من أبصارهن ويحفظن فروجهن ولا يبدين زينتهن إلا ما ظهر منها وليضربن بخمرهن على جيوبهن ولا يبدين زينتهن إلا لبعولتهن... وتوبوا إلى الله جميعا أيه المؤمنون لعلكم تفلحون» — وقل للمؤمناتِ يغضضن أبصارهنّ عن الحرام، ويحفظن فروجهنّ، ولا يُظهِرن زينتهنّ إلا ما ظهر بغيرِ قصدٍ (كالثيابِ الظاهرة)، وليُلقِين خُمُرهنّ على صدورهنّ سترًا، ولا يُبدِين زينتهنّ إلا لأزواجهنّ ومحارمهنّ المذكورين، ولا يضربن بأرجلهنّ ليُعلَم ما يخفين من الزينة؛ وتوبوا جميعًا إلى الله أيها المؤمنون لعلّكم تفلحون؛ ففي هذا فرضُ الحجابِ والحياءِ على المؤمنات، وصونُ المرأةِ عن الفتنة، وختمٌ بالأمرِ بالتوبةِ الجامعة؛ فالزمي أيتها المؤمنةُ الحجابَ والحياءَ والعفاف، وليتب الجميعُ إلى الله رجاءَ الفلاح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وليضربن بخمرهن على جيوبهن","وتوبوا إلى الله جميعا أيه المؤمنون لعلكم تفلحون"],"heart_state":{"text":"لزومُ الحجابِ والحياءِ والعفاف، والتوبةُ رجاءَ الفلاح."},"action":{"text":"لتلزم المؤمنةُ غضَّ البصرِ وحفظَ الفرجِ والحجابَ الساترَ والحياء، ولا تُبدِ زينتها إلا لمحارمها؛ وليتب الجميعُ رجالًا ونساءً إلى الله من كلِّ تقصير؛ فالتوبةُ الجامعةُ سبيلُ الفلاح، والعفافُ والحياءُ زينةُ المؤمنة."}}]},{"title":"الحضُّ على النكاحِ والعفاف","range":[32,34],"theme":"الأمرُ بتزويجِ الأيامى، والاستعفافُ لمن لم يجد، ونعمةُ الآيات","verses":[{"n":32,"reflection":{"text":"«وأنكحوا الأيامى منكم والصالحين من عبادكم وإمائكم إن يكونوا فقراء يغنهم الله من فضله والله واسع عليم» — وزوّجوا من لا زوجَ له من أحراركم، والصالحين من عبيدكم وإمائكم، إن يكونوا فقراءَ يغنهم الله من فضله، والله واسعُ الفضلِ عليمٌ بأحوالهم؛ ففي هذا الحضُّ على تيسيرِ النكاحِ صونًا للأعراض، وأنّ الفقرَ لا يمنع الزواجَ فالله يُغني؛ فيسّر الزواجَ ولا تمنعه خوفَ الفقر، وثق بأنّ الله يُغني المتزوّجَ من فضله، فالرزقُ بيده.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يغنهم الله من فضله","واسع عليم"],"heart_state":{"text":"تيسيرُ النكاحِ والثقةُ بأنّ الله يُغني."},"action":{"text":"يسّر الزواجَ لنفسك ولمن تحت يدك صونًا للأعراض، ولا تمنعه خوفَ الفقر؛ فثق بأنّ الله يُغني المتزوّجين من فضله، فالرزقُ بيده وهو واسعُ الفضل؛ فالنكاحُ عفافٌ وبركة، ومن تزوّج التماسَ العفافِ أعانه الله."}},{"n":33,"reflection":{"text":"«وليستعفف الذين لا يجدون نكاحا حتى يغنيهم الله من فضله... ولا تكرهوا فتياتكم على البغاء إن أردن تحصنا لتبتغوا عرض الحياة الدنيا ومن يكرههن فإن الله من بعد إكراههن غفور رحيم» — وليطلب العفّةَ من لا يجد ما يتزوّج به حتى يغنيه الله من فضله، ومن أراد من الأرقّاءِ أن يكاتب سيّده على مالٍ يعتق به فكاتبوه إن علمتم فيه خيرًا وأعينوه من مالِ الله، ولا تُكرِهوا إماءكم على الزنا إن أردن العفّةَ طلبًا لعرضِ الدنيا، ومن أكرههنّ فإنّ الله للمُكرَهاتِ غفورٌ رحيم؛ ففي هذا الأمرُ بالاستعفافِ عند العجزِ عن النكاح، وتحريمُ الإكراهِ على الفاحشة؛ فاستعفف عمّا حرّم الله حتى ييسّر الله، واحفظ من تحت يدك من الحرام، فالعفّةُ مطلبٌ والإكراهُ على الفاحشةِ جريمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وليستعفف الذين لا يجدون نكاحا"],"heart_state":{"text":"الاستعفافُ عند العجزِ عن النكاح، وحفظُ من تحت اليدِ من الحرام."},"action":{"text":"استعفف عمّا حرّم الله من الفاحشةِ إن لم تجد سبيلًا للنكاح، صابرًا محتسبًا حتى ييسّر الله من فضله؛ واحفظ من تحت يدك من الوقوعِ في الحرامِ أو الإكراهِ عليه؛ فالعفّةُ عبادةٌ، وطلبها عند العجزِ صبرٌ يُثاب عليه."}},{"n":34,"reflection":{"text":"«ولقد أنزلنا إليكم آيات مبينات ومثلا من الذين خلوا من قبلكم وموعظة للمتقين» — ولقد أنزلنا إليكم آياتٍ واضحاتٍ تبيّن الأحكام، وأمثالًا من أخبارِ الأممِ السابقةِ للعبرة، وموعظةً ينتفع بها المتّقون؛ ففي هذا أنّ في القرآنِ بيانًا وعبرًا وموعظة، وأنّ المنتفعَ بها المتّقون؛ فتلقَّ آياتِ الله بالقبول، واتّعظ بأمثالها وأخبارِ من مضى، وكن من المتّقين المنتفعين بالموعظة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانتفاعُ بآياتِ الله وأمثالِها وموعظتِها."},"action":{"text":"تلقَّ آياتِ الله البيّناتِ بالقبولِ والعمل، واتّعظ بأمثالها وأخبارِ الأممِ قبلك، وكن من المتّقين الذين ينتفعون بموعظتها؛ فالقرآنُ بيانٌ وعبرةٌ وموعظة، لا ينتفع بها إلا من فتح لها قلبه بالتقوى."}}]},{"title":"آيةُ النور","range":[35,35],"theme":"مثلُ نورِ الله في قلبِ المؤمن، وهدايتُه من يشاء","verses":[{"n":35,"reflection":{"text":"«الله نور السماوات والأرض مثل نوره كمشكاة فيها مصباح المصباح في زجاجة الزجاجة كأنها كوكب دري يوقد من شجرة مباركة زيتونة لا شرقية ولا غربية يكاد زيتها يضيء ولو لم تمسسه نار نور على نور يهدي الله لنوره من يشاء ويضرب الله الأمثال للناس والله بكل شيء عليم» — الله نورُ السماواتِ والأرضِ هاديهما ومنوّرهما، مثلُ نورِه (في قلبِ المؤمنِ أو الوحيِ) كمشكاةٍ (كوّةٍ) فيها مصباحٌ في زجاجةٍ صافيةٍ كأنها كوكبٌ مضيء، يُوقَد المصباحُ من زيتِ شجرةٍ مبارَكةٍ (زيتونةٍ) صافيةٍ يكاد زيتها يضيء بنفسه من صفائه، نورٌ على نور، يهدي الله لنورِه من يشاء ممّن طلب الهدى، ويضرب الأمثالَ للناسِ ليعقلوا، والله بكلِّ شيءٍ عليم؛ ففي هذا تمثيلُ نورِ الإيمانِ والهدى في قلبِ المؤمنِ بأبهى صورة، وأنّ الهدايةَ بيدِ الله؛ فاطلب نورَ الإيمانِ والهدى من الله ليضيء قلبك، فمن نوّر الله قلبه أبصر الحقَّ وسار عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الله نور السماوات والأرض","نور على نور","يهدي الله لنوره من يشاء"],"heart_state":{"text":"طلبُ نورِ الإيمانِ والهدى من الله لإضاءةِ القلب."},"action":{"text":"اطلب من الله نورَ الإيمانِ والعلمِ والهدى ليضيء قلبك كما يضيء المصباحُ في الزجاجة، فمن نوّر الله قلبه أبصر الحقَّ وسار عليه؛ فتعرّض لهذا النورِ بالإقبالِ على كتابِ الله والعملِ به، فالهدايةُ بيده يمنحها من يشاء."}}]},{"title":"عمّارُ المساجدِ الذاكرون","range":[36,38],"theme":"البيوتُ التي يُذكَر فيها اسمُ الله، ورجالٌ لا تلهيهم التجارة","verses":[{"n":36,"reflection":{"text":"«في بيوت أذن الله أن ترفع ويذكر فيها اسمه يسبح له فيها بالغدو والآصال» — هذا النورُ في بيوتٍ (المساجد) أمر الله أن تُعظَّم وتُرفَع وتُطهَّر، ويُذكَر فيها اسمه، يسبّح له فيها أوّلَ النهارِ وآخره؛ ففي هذا تعظيمُ المساجدِ وعمارتُها بالذكرِ والصلاة، وأنّ فيها نورَ الطاعة؛ فعظّم المساجدَ واعمرها بالذكرِ والصلاةِ والتسبيح، فهي بيوتُ الله التي أذن أن تُرفَع ويُذكَر فيها اسمه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["في بيوت أذن الله أن ترفع ويذكر فيها اسمه"],"heart_state":{"text":"تعظيمُ المساجدِ وعمارتُها بالذكرِ والصلاة."},"action":{"text":"عظّم بيوتَ الله (المساجد) وطهّرها واعمرها بالصلاةِ والذكرِ والتسبيحِ طرفي النهار؛ فهي البيوتُ التي أذن الله أن تُرفَع ويُذكَر فيها اسمه؛ فاجعل لك في المسجدِ نصيبًا من عبادةٍ وذكرٍ وتسبيح، فعمارتها من علاماتِ الإيمان."}},{"n":37,"reflection":{"text":"«رجال لا تلهيهم تجارة ولا بيع عن ذكر الله وإقام الصلاة وإيتاء الزكاة يخافون يوما تتقلب فيه القلوب والأبصار» — يسبّح في المساجدِ رجالٌ لا تشغلهم تجارةٌ ولا بيعٌ عن ذكرِ الله وإقامةِ الصلاةِ وإيتاءِ الزكاة، يخافون يومًا تضطرب فيه القلوبُ والأبصارُ من الهول (يوم القيامة)؛ ففي هذا مدحُ من لا تصدّه الدنيا عن طاعةِ الله، وأنّ خوفَ القيامةِ يحملهم على العبادة؛ فلا تدع تجارتك ودنياك تشغلك عن ذكرِ الله وصلاتك، واجعل خوفَ يومِ القيامةِ باعثًا لك على الطاعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["لا تلهيهم تجارة ولا بيع عن ذكر الله","يخافون يوما تتقلب فيه القلوب والأبصار"],"heart_state":{"text":"عدمُ إشغالِ الدنيا عن ذكرِ الله والصلاة."},"action":{"text":"لا تدع تجارتك ومعاشك ودنياك تشغلك عن ذكرِ الله وإقامةِ الصلاةِ وإيتاءِ الزكاة، بل اجمع بين العملِ للدنيا والقيامِ بحقِّ الله؛ واجعل خوفَ يومٍ تتقلّب فيه القلوبُ باعثًا لك على المداومةِ على الطاعة."}},{"n":38,"reflection":{"text":"«ليجزيهم الله أحسن ما عملوا ويزيدهم من فضله والله يرزق من يشاء بغير حساب» — ليجزيهم الله أحسنَ جزاءِ أعمالهم، ويزيدهم من فضله على ما يستحقّون، والله يرزق من يشاء بغيرِ حسابٍ ولا تقدير؛ ففي هذا أنّ جزاءَ الطائعين أحسنُ الجزاءِ والزيادةُ من الفضل، وأنّ عطاءَ الله بلا حساب؛ فاعمل الصالحاتِ راجيًا أحسنَ الجزاءِ والمزيدَ من فضلِ الله، فهو يرزق من يشاء ويعطي بلا حساب، فأحسن ظنّك به.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ويزيدهم من فضله","يرزق من يشاء بغير حساب"],"heart_state":{"text":"العملُ رجاءَ أحسنِ الجزاءِ والمزيدِ من فضلِ الله."},"action":{"text":"اعمل الصالحاتِ راجيًا من الله أحسنَ الجزاءِ والزيادةَ من فضله، فهو يجزي الطائعين بأحسنِ أعمالهم ويزيدهم، ويرزق من يشاء بغيرِ حساب؛ فأحسن ظنّك بكرمِ الله وسعةِ عطائه، ولا تستقلَّ عملك، فعطاؤه فوق العمل."}}]},{"title":"مثلُ أعمالِ الكفار: سرابٌ وظلمات","range":[39,40],"theme":"بطلانُ أعمالِ الكفارِ كالسراب، وحيرتُهم في ظلماتٍ متراكمة","verses":[{"n":39,"reflection":{"text":"«والذين كفروا أعمالهم كسراب بقيعة يحسبه الظمآن ماء حتى إذا جاءه لم يجده شيئا ووجد الله عنده فوفاه حسابه والله سريع الحساب» — والذين كفروا أعمالهم التي يحسبونها نافعةً كالسرابِ في الأرضِ المستويةِ يظنّه العطشانُ ماءً حتى إذا أتاه لم يجد شيئًا، ووجد الله عنده فوفّاه حسابه، والله سريعُ الحساب؛ ففي هذا أنّ أعمالَ الكفارِ باطلةٌ لا تنفعهم كالسراب، وأنّ العملَ بلا إيمانٍ هباء؛ فاحرص على أن يكون عملك مبنيًّا على الإيمانِ ليُقبَل، فالعملُ بلا إيمانٍ سرابٌ يخيب صاحبه أحوجَ ما يكون إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["أعمالهم كسراب بقيعة"],"heart_state":{"text":"الحرصُ على بناءِ العملِ على الإيمانِ لئلا يكون سرابًا."},"action":{"text":"احرص على أن يكون عملك مبنيًّا على الإيمانِ الصحيحِ والإخلاص، لئلا يكون كسرابِ أعمالِ الكفارِ التي يحسبونها نافعةً فلا يجدونها شيئًا يوم القيامة؛ فالعملُ بلا إيمانٍ هباء، فحقّق الإيمانَ أوّلًا ثم أخلص العمل."}},{"n":40,"reflection":{"text":"«أو كظلمات في بحر لجي يغشاه موج من فوقه موج من فوقه سحاب ظلمات بعضها فوق بعض إذا أخرج يده لم يكد يراها ومن لم يجعل الله له نورا فما له من نور» — أو أعمالُ الكفارِ كظلماتٍ في بحرٍ عميقٍ يغشاه موجٌ فوقه موجٌ فوقه سحاب، ظلماتٌ متراكمةٌ بعضها فوق بعض، إذا أخرج الغريقُ يده لم يكد يراها من شدّةِ الظلمة، ومن لم يجعل الله له نورَ الإيمانِ والهدى فما له من نور؛ ففي هذا تصويرُ حيرةِ الكافرِ وظلمةِ قلبه المتراكمةِ (ظلمةِ الكفرِ والجهلِ والمعصية)، وأنّ الهدايةَ نورٌ من الله؛ فاطلب نورَ الله وهداه، فمن حرمه النورَ بقي في ظلماتٍ لا يهتدي فيها، فالجأ إليه أن ينوّر قلبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ظلمات بعضها فوق بعض","ومن لم يجعل الله له نورا فما له من نور"],"heart_state":{"text":"طلبُ نورِ الله والهربُ من ظلماتِ الكفرِ والجهل."},"action":{"text":"اطلب من الله نورَ الإيمانِ والهدى والعلم، واهرب من ظلماتِ الكفرِ والجهلِ والمعاصي المتراكمة؛ فمن لم يجعل الله له نورًا بقي في حيرةٍ وظلامٍ لا يبصر فيه الحقّ؛ فالجأ إلى الله أن ينوّر قلبك وطريقك، فالنورُ كلُّه بيده."}}]},{"title":"آياتُ الله في الكونِ الدالّةُ عليه","range":[41,46],"theme":"تسبيحُ الخلق، وتسخيرُ السحابِ والليلِ والنهار، وخلقُ الدوابّ","verses":[{"n":41,"reflection":{"text":"«ألم تر أن الله يسبح له من في السماوات والأرض والطير صافات كل قد علم صلاته وتسبيحه والله عليم بما يفعلون» — ألم تعلم أنّ الله يسبّح له من في السماواتِ والأرض، والطيرُ باسطاتٍ أجنحتها في الهواء، كلُّ مخلوقٍ قد علم صلاته وتسبيحه الذي فُطِر عليه، والله عليمٌ بما يفعلون؛ ففي هذا أنّ الكونَ كلَّه يسبّح الله ويعبده، وأنّ لكلِّ مخلوقٍ عبادةً يعرفها؛ فاقتدِ بالخلقِ في تسبيحِ الله وعبادته، ولا تكن أغفلَ من الطيرِ عن ذكرِ ربّها، فالكونُ كلُّه ساجدٌ مسبّح.","source":"تفسير السعدي","grade":"ma'thur"},"names":["يسبح له من في السماوات والأرض والطير صافات"],"heart_state":{"text":"الاقتداءُ بالخلقِ في تسبيحِ الله وعبادته."},"action":{"text":"اقتدِ بالكونِ كلِّه في تسبيحِ الله وعبادته، فكلُّ مخلوقٍ يسبّحه ويعرف عبادته حتى الطيرُ في الهواء؛ فلا تكن أغفلَ من سائرِ الخلقِ عن ذكرِ ربّك، بل أكثر من تسبيحه وعبادته، فالتسبيحُ فطرةُ الوجود."}},{"n":42,"reflection":{"text":"«ولله ملك السماوات والأرض وإلى الله المصير» — ولله وحده ملكُ السماواتِ والأرضِ يتصرّف فيهما كيف يشاء، وإلى الله المرجعُ والمصيرُ للحسابِ والجزاء؛ ففي هذا إثباتُ ملكِ الله الشاملِ وأنّ المصيرَ إليه؛ فاعلم أنّ الملكَ كلَّه لله، وأنّ مصيرك إليه، فاعمل لذلك المصير، ولا تتعلّق إلا بمالكِ الملكِ الذي إليه ترجع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ولله ملك السماوات والأرض","وإلى الله المصير"],"heart_state":{"text":"استحضارُ ملكِ الله الشامل، والعملُ للمصيرِ إليه."},"action":{"text":"استحضر أنّ ملكَ السماواتِ والأرضِ لله وحده، وأنّ مصيرك ومرجعك إليه للحساب؛ فاعمل لذلك المصير، وعلّق قلبك بمالكِ الملكِ لا بمملوكٍ مثلك، فمن أيقن أنّ المصيرَ إلى الله استعدَّ للقائه."}},{"n":43,"reflection":{"text":"«ألم تر أن الله يزجي سحابا ثم يؤلف بينه ثم يجعله ركاما فترى الودق يخرج من خلاله وينزل من السماء من جبال فيها من برد فيصيب به من يشاء ويصرفه عن من يشاء يكاد سنا برقه يذهب بالأبصار» — ألم تشاهد أنّ الله يسوق السحابَ سوقًا رفيقًا، ثم يجمع بينه، ثم يجعله متراكمًا، فترى المطرَ يخرج من خلاله، وينزل من السماءِ بردًا يصيب به من يشاء ويصرفه عمّن يشاء، يكاد ضوءُ برقه يخطف الأبصار؛ ففي هذا آياتُ قدرةِ الله ولطفه وتدبيره في السحابِ والمطر، وأنّ ذلك بمشيئته؛ فتأمّل قدرةَ الله في تدبيرِ السحابِ والمطر، واعلم أنّ الرزقَ والغيثَ بيده يصيب به من يشاء، فاسأله من فضله واشكر نعمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["يزجي سحابا ثم يؤلف بينه"],"heart_state":{"text":"تأمّلُ قدرةِ الله في السحابِ والمطر، وشكرُ نعمه."},"action":{"text":"تأمّل قدرةَ الله ولطفه في سَوقِ السحابِ وتأليفه وإنزالِ المطرِ منه، واعلم أنّ الغيثَ والرزقَ بيده يصيب به من يشاء؛ فاسأله من فضله، واشكر نعمة المطرِ التي بها حياتك، ولا تنظر إلى آياته غافلًا."}},{"n":44,"reflection":{"text":"«يقلب الله الليل والنهار إن في ذلك لعبرة لأولي الأبصار» — يصرّف الله الليلَ والنهارَ ويداولهما طولًا وقصرًا وضياءً وظلامًا، إنّ في ذلك لعظةً لأصحابِ البصائر؛ ففي هذا أنّ تعاقبَ الليلِ والنهارِ آيةٌ وعبرةٌ لمن تأمّل، وأنّ في تصريفهما دلالةً على القدرةِ والرحمة؛ فتأمّل تقلّبَ الليلِ والنهارِ بعينِ البصيرة، فذلك عبرةٌ تدلّك على عظمةِ الله وقدرته ورحمته، فكن من أولي الأبصار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في تقلّبِ الليلِ والنهارِ بعينِ البصيرة."},"action":{"text":"تأمّل بعينِ البصيرةِ في تقلّبِ الليلِ والنهارِ ومداولتهما، فذلك عبرةٌ تدلّك على عظمةِ الله وقدرته ورحمته بعباده؛ فكن من أولي الأبصارِ الذين يعتبرون بآياتِ الله في الكون، لا من الغافلين الذين يمرّون عليها بلا تدبّر."}},{"n":45,"reflection":{"text":"«والله خلق كل دابة من ماء فمنهم من يمشي على بطنه ومنهم من يمشي على رجلين ومنهم من يمشي على أربع يخلق الله ما يشاء إن الله على كل شيء قدير» — والله خلق كلَّ دابّةٍ من ماء (النطفةِ أو الماءِ الذي هو أصلُ الحياة)، فمنها ما يمشي على بطنه كالحيّات، وما يمشي على رجلين كالإنسانِ والطير، وما يمشي على أربعٍ كالأنعام، يخلق الله ما يشاء، إنّ الله على كلِّ شيءٍ قدير؛ ففي هذا آيةُ تنوّعِ خلقِ الدوابِّ من أصلٍ واحد، وأنّ ذلك دليلُ كمالِ قدرةِ الله؛ فتأمّل تنوّعَ خلقِ الله من الماءِ الواحد، فذلك دليلُ قدرته التي لا يعجزها شيء، فاعبده وحده وعظّم قدرته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["خلق كل دابة من ماء","على كل شيء قدير"],"heart_state":{"text":"تأمّلُ تنوّعِ الخلقِ دليلًا على كمالِ قدرةِ الله."},"action":{"text":"تأمّل تنوّعَ خلقِ الدوابِّ من أصلٍ واحدٍ هو الماء، فذلك دليلٌ على كمالِ قدرةِ الله الذي يخلق ما يشاء كيف يشاء؛ فعظّم قدرته التي لا يعجزها شيء، واعبده وحده، فمن هذا كمالُ قدرته أحقُّ بالعبادةِ والتعظيم."}},{"n":46,"reflection":{"text":"«لقد أنزلنا آيات مبينات والله يهدي من يشاء إلى صراط مستقيم» — لقد أنزلنا آياتٍ واضحاتٍ تبيّن الحقّ، والله يهدي من يشاء ممّن طلب الهدى إلى طريقٍ مستقيم؛ ففي هذا وضوحُ آياتِ القرآن، وأنّ الهدايةَ بيدِ الله؛ فاطلب الهدايةَ من الله إلى الصراطِ المستقيم، وتدبّر آياته البيّنات، فالهدايةُ بيده يمنحها من صدق في طلبها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الهدايةِ من الله وتدبّرُ آياته البيّنات."},"action":{"text":"اطلب الهدايةَ من الله إلى صراطه المستقيم، وتعرّض لها بتدبّرِ آياته البيّناتِ والعملِ بها؛ فالهدايةُ بيده يهدي من يشاء ممّن صدق في طلبها؛ فأقبل على القرآنِ متدبّرًا، وألحَّ على الله في طلبِ الهدى."}}]},{"title":"صدقُ التحاكمِ إلى الشرعِ وطاعةُ الرسول","range":[47,54],"theme":"إعراضُ المنافقين عن التحاكمِ، وموقفُ المؤمنين، وثمرةُ الطاعة","verses":[{"n":47,"reflection":{"text":"«ويقولون آمنا بالله وبالرسول وأطعنا ثم يتولى فريق منهم من بعد ذلك وما أولئك بالمؤمنين» — ويقول المنافقون: آمنّا بالله وبالرسولِ وأطعنا، ثم يُعرِض فريقٌ منهم عن الطاعةِ بعد ذلك، وما أولئك بالمؤمنين حقًّا؛ ففي هذا أنّ الإيمانَ قولٌ وعمل، وأنّ من خالف قولُه فعلَه فليس بمؤمنٍ صادق؛ فليكن إيمانك مقرونًا بالطاعةِ والعمل، لا مجردَ دعوى، فالمؤمنُ الصادقُ يصدّق قوله عمله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يكون الإيمانُ مقرونًا بالطاعةِ والعمل."},"action":{"text":"ليكن إيمانك مقرونًا بالطاعةِ والعملِ لا مجردَ دعوى باللسان؛ فمن قال آمنت ثم أعرض عن طاعةِ الله ورسوله فليس بمؤمنٍ صادق؛ فحقّق إيمانك بالامتثالِ والانقياد، فالمؤمنُ يصدّق قوله عمله."}},{"n":48,"reflection":{"text":"«وإذا دعوا إلى الله ورسوله ليحكم بينهم إذا فريق منهم معرضون» — وإذا دُعِي المنافقون إلى حكمِ الله ورسوله ليفصل بينهم أعرض فريقٌ منهم؛ ففي هذا أنّ الإعراضَ عن التحاكمِ إلى الشرعِ من علاماتِ النفاق، وأنّ المؤمنَ يرضى بحكمِ الله؛ فاحرص على التحاكمِ إلى شرعِ الله والرضا به، ولا تُعرِض عنه إلى غيره، فالإعراضُ عن حكمِ الله علامةُ ضعفِ الإيمان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التحاكمُ إلى شرعِ الله والرضا به."},"action":{"text":"احرص على التحاكمِ إلى شرعِ الله ورسوله في خصوماتك وأمورك، وارضَ بحكمه؛ ولا تُعرِض عنه إلى قوانينِ الناسِ وأهوائهم؛ فالإعراضُ عن حكمِ الله من علاماتِ النفاق، والرضا به من صدقِ الإيمان."}},{"n":49,"reflection":{"text":"«وإن يكن لهم الحق يأتوا إليه مذعنين» — وإن كان الحكمُ لصالحهم أتوا إلى الرسولِ منقادين مسرعين؛ ففي هذا فضحُ المنافقِ الذي يتحاكم إلى الشرعِ إذا وافق هواه ويُعرِض إذا خالفه، وأنّ اتّباعَ الهوى يفسد التحاكم؛ فاحذر أن تتحاكم إلى الشرعِ عند موافقتِه لهواك فقط، بل ارضَ بحكمِ الله لك وعليك، فذلك صدقُ الإيمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرضا بحكمِ الله لك وعليك لا عند الهوى فقط."},"action":{"text":"ارضَ بحكمِ الله لك وعليك على السواء، لا تتحاكم إليه إذا وافق هواك وتُعرِض إذا خالفه؛ فذلك فعلُ المنافقين؛ فالمؤمنُ الصادقُ ينقاد لحكمِ الله في كلِّ حال، سواءٌ كان له أم عليه، فالحقُّ لا يتبع الهوى."}},{"n":50,"reflection":{"text":"«أفي قلوبهم مرض أم ارتابوا أم يخافون أن يحيف الله عليهم ورسوله بل أولئك هم الظالمون» — أفي قلوبهم شكٌّ ونفاق، أم ارتابوا في نبوّته، أم يخافون أن يجور الله ورسوله في الحكم؟ بل أولئك هم الظالمون بإعراضهم؛ ففي هذا أنّ الإعراضَ عن حكمِ الله ظلمٌ ومرضُ قلب، وأنّ حكمَ الله ورسوله عدلٌ لا جورَ فيه؛ فاعلم أنّ حكمَ الله عدلٌ محض، فلا تخف حيفًا فيه، بل سلّم له، والإعراضُ عنه ظلمٌ لنفسك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمِ الله الذي هو عدلٌ لا جورَ فيه."},"action":{"text":"سلّم لحكمِ الله ورسوله فإنه عدلٌ محضٌ لا جورَ فيه ولا حيف، ولا تخف منه على حقّك؛ فالإعراضُ عنه ظلمٌ لنفسك ومرضٌ في القلب؛ فأحسن الظنَّ بشرعِ الله، واعلم أنّ فيه صلاحك وعدلك، فانقد له."}},{"n":51,"reflection":{"text":"«إنما كان قول المؤمنين إذا دعوا إلى الله ورسوله ليحكم بينهم أن يقولوا سمعنا وأطعنا وأولئك هم المفلحون» — إنما قولُ المؤمنين الصادقين إذا دُعوا إلى حكمِ الله ورسوله أن يقولوا: سمعنا وأطعنا، وأولئك هم الفائزون؛ ففي هذا أنّ شعارَ المؤمنِ «سمعنا وأطعنا» عند حكمِ الله، وأنّ الفلاحَ في الانقياد؛ فليكن شعارك عند أمرِ الله وحكمه «سمعنا وأطعنا»، فبالانقيادِ التامِّ يكون الفلاح، وهو صفةُ المؤمنين الصادقين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["أن يقولوا سمعنا وأطعنا","وأولئك هم المفلحون"],"heart_state":{"text":"جعلُ شعارِ العبدِ «سمعنا وأطعنا» عند حكمِ الله."},"action":{"text":"ليكن شعارك عند كلِّ أمرٍ من الله وحكمٍ لرسوله «سمعنا وأطعنا»، منقادًا بلا تردّدٍ ولا اعتراض؛ فبهذا الانقيادِ يكون الفلاحُ والفوز، وهو صفةُ المؤمنين الصادقين؛ فسلّم لأمرِ الله راضيًا مطمئنًّا."}},{"n":52,"reflection":{"text":"«ومن يطع الله ورسوله ويخش الله ويتقه فأولئك هم الفائزون» — ومن يطع الله ورسوله في الأمرِ والنهي، ويخشَ الله فيما مضى من ذنوبه، ويتّقه فيما يستقبل، فأولئك هم الفائزون بكلِّ خير؛ ففي هذا أنّ الفوزَ بجمعِ الطاعةِ والخشيةِ والتقوى، وأنها جماعُ الخير؛ فاجمع بين طاعةِ الله ورسوله وخشيةِ الله وتقواه، فبهذه الثلاثِ يكون الفوزُ الحقيقيُّ في الدنيا والآخرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ومن يطع الله ورسوله ويخش الله ويتقه فأولئك هم الفائزون"],"heart_state":{"text":"الجمعُ بين الطاعةِ والخشيةِ والتقوى للفوز."},"action":{"text":"اجمع بين طاعةِ الله ورسوله في الأمرِ والنهي، وخشيةِ الله على ما مضى، وتقواه فيما يستقبل؛ فبهذه الثلاثِ يكون الفوزُ الحقيقيُّ؛ فاجعلها منهجك: طاعةً وخشيةً وتقوى، فالفائزون هم الجامعون لها."}},{"n":53,"reflection":{"text":"«وأقسموا بالله جهد أيمانهم لئن أمرتهم ليخرجن قل لا تقسموا طاعة معروفة إن الله خبير بما تعملون» — وأقسم المنافقون بالله مجتهدين في أيمانهم لئن أمرتهم بالجهادِ ليخرجنّ، قل: لا تقسموا، المطلوبُ طاعةٌ معروفةٌ بالفعلِ لا بالقول، إنّ الله خبيرٌ بما تعملون؛ ففي هذا أنّ العبرةَ بالطاعةِ الفعليّةِ لا بالأيمانِ والدعاوى، وأنّ الله خبيرٌ بالحقائق؛ فاجعل عبرتك بالعملِ لا بالقول، ولا تُكثِر الحلفَ والدعاوى، فالله خبيرٌ بحقيقةِ عملك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العبرةُ بالطاعةِ الفعليّةِ لا بالدعاوى والأيمان."},"action":{"text":"اجعل عبرتك بالطاعةِ الفعليّةِ الصادقةِ لا بكثرةِ الحلفِ والدعاوى بالقول؛ فالله خبيرٌ بحقيقةِ عملك لا تنطلي عليه الأيمان؛ فبرهن على صدقك بالفعلِ لا باللسان، والطاعةُ المعروفةُ خيرٌ من ألفِ يمين."}},{"n":54,"reflection":{"text":"«قل أطيعوا الله وأطيعوا الرسول فإن تولوا فإنما عليه ما حمل وعليكم ما حملتم وإن تطيعوه تهتدوا وما على الرسول إلا البلاغ المبين» — قل: أطيعوا الله وأطيعوا الرسول، فإن أعرضتم فإنما على الرسولِ ما كُلِّف من البلاغِ وعليكم ما كُلِّفتم من الطاعة، وإن تطيعوه تهتدوا، وما على الرسولِ إلا التبليغُ الواضح؛ ففي هذا أنّ الهدايةَ في طاعةِ الرسول، وأنّ وظيفتَه البلاغُ لا الإكراه؛ فأطع الله ورسوله تهتدِ، فالسعادةُ كلُّها في طاعتهما، والمسؤوليّةُ عليك في الاستجابة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وإن تطيعوه تهتدوا","وما على الرسول إلا البلاغ المبين"],"heart_state":{"text":"طاعةُ الله ورسوله سبيلًا للهداية."},"action":{"text":"أطع الله ورسوله في الأمرِ والنهي تهتدِ وتسعد، فالهدايةُ كلُّها في طاعتهما؛ فوظيفةُ الرسولِ البلاغُ، والمسؤوليّةُ عليك في الاستجابةِ والطاعة؛ فبادر بالامتثال، ولا تُعرِض فتتحمّل وزرَ إعراضك."}}]},{"title":"وعدُ الاستخلافِ والتمكين","range":[55,57],"theme":"وعدُ الله المؤمنين بالاستخلافِ والأمن، والأمرُ بالصلاةِ والطاعة","verses":[{"n":55,"reflection":{"text":"«وعد الله الذين آمنوا منكم وعملوا الصالحات ليستخلفنهم في الأرض كما استخلف الذين من قبلهم وليمكنن لهم دينهم الذي ارتضى لهم وليبدلنهم من بعد خوفهم أمنا يعبدونني لا يشركون بي شيئا ومن كفر بعد ذلك فأولئك هم الفاسقون» — وعد الله الذين جمعوا الإيمانَ والعملَ الصالحَ أن يجعلهم خلفاءَ في الأرضِ يمكّنهم فيها كما مكّن من قبلهم، وأن يمكّن لهم دينَهم الذي رضيه لهم (الإسلام)، وأن يبدّلهم بعد خوفهم أمنًا، بشرطِ أن يعبدوه وحده لا يشركوا به شيئًا، ومن كفر بعد ذلك فأولئك هم الخارجون عن طاعته؛ ففي هذا أنّ التمكينَ والاستخلافَ ثمرةُ الإيمانِ والعملِ والتوحيد، وأنّ الأمنَ من الله؛ فحقّق الإيمانَ والعملَ والتوحيدَ الخالص، فبها يأتي الاستخلافُ والتمكينُ والأمن، فالنصرُ مشروطٌ بالطاعةِ والإخلاص.","source":"تفسير السعدي","grade":"ma'thur"},"names":["ليستخلفنهم في الأرض","وليبدلنهم من بعد خوفهم أمنا","يعبدونني لا يشركون بي شيئا"],"heart_state":{"text":"تحقيقُ الإيمانِ والعملِ والتوحيدِ لنيلِ التمكينِ والأمن."},"action":{"text":"حقّق الإيمانَ والعملَ الصالحَ والتوحيدَ الخالصَ (تعبد الله لا تشرك به شيئًا)، فبها وعد الله المؤمنين بالاستخلافِ في الأرضِ وتمكينِ الدينِ وتبديلِ الخوفِ أمنًا؛ فالنصرُ والتمكينُ ثمرةُ الطاعةِ والإخلاص، فاجتهد فيهما لتنال الوعد."}},{"n":56,"reflection":{"text":"«وأقيموا الصلاة وآتوا الزكاة وأطيعوا الرسول لعلكم ترحمون» — وأقيموا الصلاةَ في أوقاتها، وآتوا الزكاةَ المفروضة، وأطيعوا الرسولَ فيما أمر ونهى، رجاءَ أن تُرحَموا؛ ففي هذا أنّ الرحمةَ تُنال بإقامةِ الصلاةِ وإيتاءِ الزكاةِ وطاعةِ الرسول، وأنها أسبابُ رحمةِ الله؛ فأقم الصلاةَ وآتِ الزكاةَ وأطع الرسول، فبهذه الثلاثِ تُرجى رحمةُ الله التي بها الفوز.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["وأقيموا الصلاة وآتوا الزكاة وأطيعوا الرسول لعلكم ترحمون"],"heart_state":{"text":"إقامةُ الصلاةِ والزكاةِ وطاعةُ الرسولِ رجاءَ الرحمة."},"action":{"text":"أقم الصلاةَ في أوقاتها، وآتِ الزكاةَ في مصارفها، وأطع الرسولَ فيما جاء به؛ فبهذه الثلاثِ تُرجى رحمةُ الله التي بها فوزك في الدنيا والآخرة؛ فاجعلها ديدنك، فالرحمةُ مقرونةٌ بطاعةِ الله ورسوله."}},{"n":57,"reflection":{"text":"«لا تحسبن الذين كفروا معجزين في الأرض ومأواهم النار ولبئس المصير» — لا تظنّنّ يا محمد أنّ الكفارَ يفوتوننا ويعجزوننا في الأرضِ فيفلتون من عذابنا، ومأواهم النارُ وبئس المصير؛ ففي هذا أنّ الكافرَ لا يعجز الله ولا يفوته، وأنّ مصيرَه النار؛ فلا يغرّنك قوّةُ الكفارِ وتمكّنهم في الأرض، فإنهم لا يعجزون الله، ومصيرهم النار، فالعاقبةُ لأهلِ الإيمان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العلمُ بأنّ الكافرَ لا يعجز الله وأنّ مصيرَه النار."},"action":{"text":"لا يغرّنك قوّةُ الكفارِ وتمكّنهم في الأرض، ولا تظنّهم يفوتون الله ويعجزونه، فمأواهم النارُ وبئس المصير؛ فالعاقبةُ لأهلِ الإيمانِ والطاعة، فاثبت على الحقِّ ولا تهبهم، فالله محيطٌ بهم قادرٌ عليهم."}}]},{"title":"آدابُ الاستئذانِ في البيوتِ والأكلِ من بيوتِ الأقارب","range":[58,61],"theme":"استئذانُ المماليكِ والأطفال، ورخصةُ القواعد، وإباحةُ الأكلِ من بيوتِ الأقارب","verses":[{"n":58,"reflection":{"text":"«يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات من قبل صلاة الفجر وحين تضعون ثيابكم من الظهيرة ومن بعد صلاة العشاء ثلاث عورات لكم ليس عليكم ولا عليهم جناح بعدهن طوافون عليكم بعضكم على بعض كذلك يبين الله لكم الآيات والله عليم حكيم» — يا أيها المؤمنون ليستأذنكم مماليككم وأطفالكم الذين لم يبلغوا الحلمَ في ثلاثةِ أوقات: قبل صلاةِ الفجر، ووقتَ القيلولةِ حين تضعون ثيابكم، وبعد صلاةِ العشاء، فهذه ثلاثُ أوقاتِ عورةٍ (خلوة)، لا إثمَ عليكم ولا عليهم في الدخولِ بلا استئذانٍ بعدها لكثرةِ الطوافِ والمخالطة، كذلك يبيّن الله لكم الآياتِ والله عليمٌ حكيم؛ ففي هذا تشريعُ أدبِ الاستئذانِ حتى للأطفالِ والمماليكِ في أوقاتِ الخلوةِ صيانةً للعورات؛ فعلّم أهلك وأطفالك أدبَ الاستئذانِ في أوقاتِ الخلوة، فذلك من حفظِ العوراتِ وصونِ الحرمات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["ثلاث عورات لكم","والله عليم حكيم"],"heart_state":{"text":"تعليمُ الأهلِ والأطفالِ أدبَ الاستئذانِ صيانةً للعورات."},"action":{"text":"علّم أهلك وأطفالك ومن تحت يدك أدبَ الاستئذانِ في أوقاتِ الخلوةِ الثلاثِ صيانةً للعوراتِ والحرمات؛ فالشرعُ راعى الخصوصيّةَ حتى داخل البيتِ الواحد؛ فرَبِّ أهلك على الحياءِ والأدبِ في الدخولِ والخروج."}},{"n":59,"reflection":{"text":"«وإذا بلغ الأطفال منكم الحلم فليستأذنوا كما استأذن الذين من قبلهم كذلك يبين الله لكم آياته والله عليم حكيم» — وإذا بلغ أطفالكم الحلمَ (البلوغ) فليستأذنوا في جميعِ الأوقاتِ كما يستأذن البالغون من قبلهم، كذلك يبيّن الله لكم آياته والله عليمٌ حكيم؛ ففي هذا أنّ البالغَ يلزمه الاستئذانُ في كلِّ وقتٍ لا في الأوقاتِ الثلاثِ فقط، وأنّ الأحكامَ تتدرّج مع البلوغ؛ فرَبِّ أولادك على الاستئذانِ والأدب، وعلّمهم أحكامَ البلوغِ حين يبلغون، فالتربيةُ على الأدبِ تبدأ مبكّرًا وتكتمل بالبلوغ.","source":"تفسير السعدي","grade":"ma'thur"},"names":["فليستأذنوا كما استأذن الذين من قبلهم"],"heart_state":{"text":"تربيةُ الأولادِ على الاستئذانِ وأحكامِ البلوغ."},"action":{"text":"رَبِّ أولادك على أدبِ الاستئذانِ منذ الصغر، وعلّمهم أحكامَ البلوغِ حين يبلغون، فالبالغُ يلزمه الاستئذانُ في كلِّ وقت؛ فالتربيةُ على الأدبِ والحياءِ تبدأ مبكّرًا وتكتمل بالبلوغ، فتعاهد أهلك بالتعليمِ والتأديب."}},{"n":60,"reflection":{"text":"«والقواعد من النساء اللاتي لا يرجون نكاحا فليس عليهن جناح أن يضعن ثيابهن غير متبرجات بزينة وأن يستعففن خير لهن والله سميع عليم» — والنساءُ العجائزُ اللاتي قعدن عن الحيضِ والولدِ ولا يرغبن في النكاحِ ولا يُرغَب فيهنّ، ليس عليهنّ إثمٌ أن يضعن بعضَ ثيابهنّ (كالجلبابِ الفوقيّ) غيرَ مُظهِراتٍ لزينة، واستعفافهنّ بالتستّرِ خيرٌ لهنّ، والله سميعٌ عليم؛ ففي هذا رخصةٌ للقواعدِ مع الحضِّ على الاستعفافِ والتستّر، وأنّ العفّةَ أفضل؛ فتأمّل رحمةَ الشرعِ ويُسرَه، واعلم أنّ التستّرَ والعفّةَ خيرٌ حتى مع الرخصة، فالحياءُ زينةٌ في كلِّ سنّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":["وأن يستعففن خير لهن","والله سميع عليم"],"heart_state":{"text":"الحضُّ على العفّةِ والتستّرِ حتى مع الرخصة."},"action":{"text":"تأمّل رحمةَ الشرعِ ويُسرَه في الرخصةِ للقواعدِ من النساء، واعلم أنّ الاستعفافَ والتستّرَ خيرٌ حتى مع وجودِ الرخصة؛ فالحياءُ والعفّةُ زينةٌ للمرأةِ في كلِّ سنّ؛ فاطلبي الأفضلَ الأكملَ من التستّرِ والعفاف، فهو خيرٌ لكِ عند الله."}},{"n":61,"reflection":{"text":"«ليس على الأعمى حرج ولا على الأعرج حرج ولا على المريض حرج ولا على أنفسكم أن تأكلوا من بيوتكم أو بيوت آبائكم... أو صديقكم ليس عليكم جناح أن تأكلوا جميعا أو أشتاتا فإذا دخلتم بيوتا فسلموا على أنفسكم تحية من عند الله مباركة طيبة كذلك يبين الله لكم الآيات لعلكم تعقلون» — ليس على الأعمى ولا الأعرجِ ولا المريضِ حرجٌ في التخلّفِ عمّا يعجزون عنه، ولا حرجَ عليكم أن تأكلوا من بيوتكم أو بيوتِ آبائكم وأمّهاتكم وإخوانكم وأخواتكم وأعمامكم وعمّاتكم وأخوالكم وخالاتكم أو ما ملكتم مفاتحه أو صديقكم، لا إثمَ أن تأكلوا مجتمعين أو متفرّقين، فإذا دخلتم بيوتًا فسلّموا على أهلها (أنفسكم) تحيّةً من عند الله مبارَكةً طيّبة، كذلك يبيّن الله لكم الآياتِ لعلّكم تعقلون؛ ففي هذا رفعُ الحرجِ ويُسرُ الشرعِ في المؤاكلةِ بين الأقارب، والأمرُ بإفشاءِ السلامِ عند الدخول؛ فتأمّل يُسرَ الشرعِ ورحمته، وأفشِ السلامَ عند دخولك البيوت، فالسلامُ تحيّةٌ مبارَكةٌ من عند الله تنشر المحبّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["فسلموا على أنفسكم تحية من عند الله مباركة طيبة"],"heart_state":{"text":"تأمّلُ يُسرِ الشرع، وإفشاءُ السلامِ عند الدخول."},"action":{"text":"تأمّل يُسرَ الشرعِ ورحمته في رفعِ الحرجِ والمؤاكلةِ بين الأقاربِ والأصدقاء؛ وأفشِ السلامَ إذا دخلت بيتًا، فهو تحيّةٌ مبارَكةٌ طيّبةٌ من عند الله تنشر المحبّةَ والألفة؛ فاجعل السلامَ ديدنك، فبه تُبنى الأخوّةُ وتُنشَر المودّة."}}]},{"title":"أدبُ المؤمنين مع الرسولِ وخاتمةُ السورة","range":[62,64],"theme":"استئذانُ المؤمنين للنبيِّ، وتوقيرُه، وإحاطةُ علمِ الله","verses":[{"n":62,"reflection":{"text":"«إنما المؤمنون الذين آمنوا بالله ورسوله وإذا كانوا معه على أمر جامع لم يذهبوا حتى يستأذنوه إن الذين يستأذنونك أولئك الذين يؤمنون بالله ورسوله فإذا استأذنوك لبعض شأنهم فأذن لمن شئت منهم واستغفر لهم الله إن الله غفور رحيم» — إنما المؤمنون الصادقون الذين آمنوا بالله ورسوله، وإذا كانوا مع النبيِّ ﷺ في أمرٍ يجمعهم (كالجهادِ والجمعة) لم ينصرفوا حتى يستأذنوه، إنّ الذين يستأذنونك أولئك المؤمنون حقًّا، فإذا استأذنوك لحاجةٍ لهم فأذن لمن شئت منهم واستغفر لهم الله، إنّ الله غفورٌ رحيم؛ ففي هذا أنّ الأدبَ مع الرسولِ والاستئذانَ من علاماتِ الإيمانِ الصادق؛ فتأدّب مع أمرِ الله ورسوله، والزم جماعةَ المسلمين في أمورهم الجامعة، ولا تنصرف عن الأمرِ الجامعِ إلا بإذنٍ وعذر.","source":"تفسير السعدي","grade":"ma'thur"},"names":["إن الذين يستأذنونك أولئك الذين يؤمنون بالله ورسوله"],"heart_state":{"text":"التأدّبُ مع أمرِ الرسولِ ولزومُ الجماعةِ في الأمرِ الجامع."},"action":{"text":"تأدّب مع أمرِ الله ورسوله، والزم جماعةَ المسلمين في أمورهم الجامعةِ كالجمعةِ والجهادِ والشورى، ولا تنصرف عنها إلا بإذنٍ وعذر؛ فالاستئذانُ والأدبُ من علاماتِ الإيمانِ الصادق؛ فوقّر أمرَ الجماعةِ ولا تتخلّف عنها بلا عذر."}},{"n":63,"reflection":{"text":"«لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا قد يعلم الله الذين يتسللون منكم لواذا فليحذر الذين يخالفون عن أمره أن تصيبهم فتنة أو يصيبهم عذاب أليم» — لا تجعلوا نداءكم للرسولِ ودعاءه لكم كنداءِ بعضكم بعضًا (بل وقّروه وعظّموه)، قد يعلم الله الذين ينسلّون خفيةً من مجلسه مستترين، فليحذر الذين يخالفون أمرَ الرسولِ أن تصيبهم فتنةٌ في قلوبهم أو عذابٌ أليم؛ ففي هذا وجوبُ توقيرِ الرسولِ ﷺ، والتحذيرُ من مخالفةِ أمره؛ فوقّر النبيَّ ﷺ وسنّتَه، واحذر مخالفةَ أمره، فإنّ مخالفةَ أمرِه سببُ الفتنةِ والعذاب، فالزم اتّباعه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["فليحذر الذين يخالفون عن أمره أن تصيبهم فتنة أو يصيبهم عذاب أليم"],"heart_state":{"text":"توقيرُ الرسولِ وسنّتِه، والحذرُ من مخالفةِ أمره."},"action":{"text":"وقّر النبيَّ ﷺ وعظّم سنّته وأمره، ولا تجعل هديه كأقوالِ الناس؛ واحذر مخالفةَ أمره فإنها سببُ الفتنةِ في القلبِ والعذابِ الأليم؛ فمن أعرض عن سنّته خُشِي عليه الزيغ؛ فالزم اتّباعه في الظاهرِ والباطن."}},{"n":64,"reflection":{"text":"«ألا إن لله ما في السماوات والأرض قد يعلم ما أنتم عليه ويوم يرجعون إليه فينبئهم بما عملوا والله بكل شيء عليم» — ألا إنّ لله وحده ما في السماواتِ والأرضِ ملكًا وخلقًا، قد يعلم ما أنتم عليه من الأحوالِ والنيّات، ويومَ يُرجَعون إليه يخبرهم بما عملوا فيجازيهم، والله بكلِّ شيءٍ عليم؛ ففي هذا خاتمةٌ بإثباتِ ملكِ الله وإحاطةِ علمِه بالسرِّ والعلن، وأنّ المرجعَ إليه للجزاء؛ فراقب الله المحيطَ بأحوالك، واعمل لمرجعك إليه، فهو يعلم ما أنت عليه وسينبّئك بعملك، فاستعدَّ للقائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["والله بكل شيء عليم"],"heart_state":{"text":"مراقبةُ الله المحيطِ علمُه، والعملُ للمرجعِ إليه."},"action":{"text":"راقب الله الذي له ملكُ السماواتِ والأرض، ويعلم ما أنت عليه من ظاهرٍ وباطن، وستُرجَع إليه فينبّئك بعملك ويجازيك؛ فاجعل مراقبته نصب عينيك، واعمل لمرجعك إليه بالإخلاصِ والطاعة، فمن أيقن بإحاطةِ علمه استقام."}}]}],"coverage":{"covered":64,"total":64}};
